package com.manishrawat.realestate.servlet; import com.manishrawat.realestate.dao.*; import com.manishrawat.realestate.service.PropertyService; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.*; @WebServlet("/admin") public class AdminServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{r.setAttribute("users",new UserDAO().findAll());r.setAttribute("properties",new PropertyService().all());r.setAttribute("logs",new ActivityDAO().recent());r.getRequestDispatcher("/WEB-INF/views/admin/index.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{try{new PropertyService().approve(Integer.parseInt(r.getParameter("id")),"APPROVED".equals(r.getParameter("status")));s.sendRedirect("admin");}catch(Exception e){throw new IOException(e);}}}
